arguments.command:
for r in run-b run-c; do echo "=== $r"; zcat $r/master.log.gz | python3 -c "
import sys, json
from collections import Counter
kinds=Counter(); msgs=[]
for line in sys.stdin:
    try: r=json.loads(line)
    except Exception: continue
    m=r.get('msg','')
    # classify
    if 'rollout' in m.lower() and ('reward' in m.lower() or 'complete' in m.lower() or 'collecting' in m.lower()): kinds['rollout']+=1; msgs.append(m[:200])
    elif 'train/' in m: kinds['train']+=1; msgs.append(m[:200])
    elif 'agentic' in m.lower(): kinds['agentic']+=1; msgs.append(m[:150])
print(kinds)
for m in msgs[:25]: print(m)
"; done

