for r in run-b run-c; do echo "=== $r"; zcat $r/master.log.gz | python3 -c "
import sys, json, re
from collections import Counter
pat=Counter()
for line in sys.stdin:
    try: r=json.loads(line)
    except Exception: continue
    m=r.get('msg','')
    for kw in ['reward','solve','advantage','Recycl','recycl','abort','weight_stale','staleness','branches','filter','First rollout sample','complete in']:
        if kw in m:
            pat[kw]+=1
            if pat[kw]<6: print(kw,'|',m[:240])
print(dict(pat))
"; done 2>/dev/null | head -80

